import json,pathlib,html,zipfile
ROOT=pathlib.Path(__file__).resolve().parent.parent;m=json.loads((ROOT/'data/listening-resources.json').read_text());resources=m['resources'];esc=html.escape
STYLE='''*{box-sizing:border-box}body{margin:0;font:15px/1.7 system-ui,"Microsoft YaHei",sans-serif;background:#f4f6fa;color:#172436}main{max-width:1040px;margin:auto;padding:32px 20px}header{margin-bottom:24px}h1{font-size:28px;margin:0}h2{font-size:19px;margin:0 0 8px}p{margin:8px 0}.muted{color:#68768b;font-size:13px}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}article{background:white;border:1px solid #dfe5ec;border-radius:16px;padding:22px;min-width:0}.badge{font-size:12px;padding:4px 9px;color:#087f64;background:#e7f6f1;border-radius:99px;display:inline-block;margin-bottom:10px}audio{width:100%;margin:10px 0}a{color:#008c6d;text-underline-offset:3px}.links{display:flex;flex-wrap:wrap;gap:14px}summary{cursor:pointer;color:#008c6d}details{margin-top:12px}details p{white-space:pre-wrap}.notice{border-left:3px solid #12a37c;padding-left:14px}.filter{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}.filter button{border:1px solid #dfe5ec;background:white;color:#172436;border-radius:999px;padding:8px 14px;cursor:pointer;font:inherit}.filter button.on{color:white;background:#12a37c;border-color:#12a37c}article[hidden]{display:none}@media(max-width:680px){.cards{grid-template-columns:minmax(0,1fr)}main{padding:20px 12px}article{padding:18px}}'''
def render(mode):
 cards=[]
 for r in resources:
  filename=pathlib.Path(r['clipPath']).name
  if mode=='web':audio='/listening-audio/'+filename;original='/listening-originals/'+r['originalPath'].split('originals/',1)[1]
  elif mode=='pack':audio='audio/'+filename;original=r['originalUrl']
  else:audio='../'+r['clipPath'];original=r['originalPath'].removeprefix('listening-resources/')
  transcript=r.get('transcript');reference=f'<details><summary>查看来源原文（听完再看）</summary><p>{esc(transcript)}</p></details>' if transcript else f'<p class="muted">'+(f'<a href="{esc(r["transcriptUrl"],quote=True)}" target="_blank" rel="noopener">查看作者提供的文字资料 ↗</a>' if r.get('transcriptUrl') else '暂无已核对的逐句文字。')+'</p>'
  cards.append(f'''<article data-category="{esc(r['category'],quote=True)}"><span class="badge">{esc(r['category'])} · {esc(r['level'])}</span><h2>{esc(r['title'])}</h2><p class="muted">片段 {r['clip']['duration']:.0f} 秒 · 完整原声 {r['original']['duration']/60:.1f} 分钟</p><p>{esc(r['summary'])}</p><audio controls preload="none" src="{esc(audio,quote=True)}" aria-label="{esc(r['title'],quote=True)}"></audio><div class="links"><a href="{esc(audio,quote=True)}" download="{esc(filename)}">下载短音频</a><a href="{esc(original,quote=True)}" target="_blank" rel="noopener">完整原声</a><a href="{esc(r['sourceUrl'],quote=True)}" target="_blank" rel="noopener">原始来源 ↗</a></div>{reference}<p class="muted">{esc(r['attribution'])}</p></article>''')
 return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>粤语听力素材库</title><style>{STYLE}</style></head><body><main><header><h1>粤语听力素材库</h1><p class="muted">收集日期：2026-10-05 · 10 组独立外部素材 · 真人原声</p><p>先听一遍，用普通话说出你理解的意思，再对照来源文字。可以重复播放、慢放或分段听。</p><p class="notice muted">本页用于试听与选材。这批新素材尚未整理自动评分标准；自然对话和广播片段也尚未逐句核对。已配置评分的练习仍在「听力训练」页面。</p></header><nav class="filter" aria-label="素材类型"><button class="on" data-filter="all" type="button">全部 10</button><button data-filter="入门故事" type="button">入门故事 5</button><button data-filter="自然对话" type="button">自然对话 4</button><button data-filter="广播" type="button">广播 1</button></nav><section class="cards">{''.join(cards)}</section><p class="muted">影片候选：YouTube 要求登录确认非机器人，哔哩哔哩返回 HTTP 412；本批没有下载成功的影视视频文件。</p></main><script>document.querySelector('.filter').addEventListener('click',e=>{{const b=e.target.closest('[data-filter]');if(!b)return;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('on',x===b));document.querySelectorAll('article').forEach(x=>{{x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter;if(x.hidden)x.querySelector('audio').pause()}})}});document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(b=>{{if(b!==a)b.pause()}})));</script></body></html>'''
(ROOT/'public/listening-resources.html').write_text(render('web'))
(ROOT/'listening-resources/index.html').write_text(render('offline'))
lines=['# 已下载粤语听力资源','', '收集日期：2026-10-05。独立于现有朗读课文。','', '- 10 份完整原声，约 65.5 分钟。','- 10 段短音频，38–75 秒，共约 9.4 分钟。','- 新下载的原始音频和短音频共约 53.8MB；另有当前听力任务的本地缓存。','- 入门故事按原站完整页面边界拼接；成人对话优先在停顿处剪辑，片段内容及边界尚未逐句审核。','- 新素材供试听与选材，尚未准备自动评分信息点。','', '## 试听与下载','', '直接打开本目录的 `index.html` 可以离线试听。网页中「听力训练 → 试听已下载的素材」也能打开素材库。','', '`short-listening-pack.zip` 包含全部 10 段短音频和可离线播放的目录，解压后打开 `index.html`；压缩包不包含完整原声。','', '## 已下载清单','', '| 内容 | 类型 | 片段 | 完整原声 | 来源 |','| --- | --- | --- | --- | --- |']
for r in resources:lines.append(f"| {r['title']} | {r['category']} | {r['clip']['duration']:.1f} 秒 | {r['original']['duration']/60:.1f} 分钟 | [{r['sourceName']}]({r['sourceUrl']}) |")
lines+=['', '## 文件位置与恢复','', '完整原声：`originals/2026-10-05/`。短音频：项目的 `public/listening-audio/`。来源、原文状态、剪辑起止和 SHA-256 校验值：`data/listening-resources.json`。','', '音频文件较大，已加入 `.gitignore`，仍完整保留在本机。需要重新下载时运行 `python3 scripts/collect-listening-resources.py`，仅检查本地文件时运行 `python3 scripts/collect-listening-resources.py --verify-only`。依赖 Python 3.11+、ffmpeg、ffprobe。','', '## 未下载成功的候选','', '- TVB《爱回家》YouTube 片段：平台要求登录确认非机器人。','- 哔哩哔哩粤语日常对话、影视教学、茶餐厅对话：网页与公开元数据接口返回 HTTP 412。','- 未使用账户或 Cookie；这些失败项没有计入已下载数量。','', '当前听力训练原有三组《出街玩》的 12 条片段也已下载并改成本地播放。']
(ROOT/'listening-resources/README.md').write_text('\n'.join(lines)+'\n')
zipPath=ROOT/'listening-resources/short-listening-pack.zip'
with zipfile.ZipFile(zipPath,'w',compression=zipfile.ZIP_DEFLATED) as z:
 z.writestr('index.html',render('pack'));z.writestr('README.txt','解压后打开 index.html 即可离线播放。10 段真人粤语短音频，约 9.4 分钟。完整节目不在此压缩包内。来源与文字资料链接在目录中。新素材尚未准备自动评分标准。')
 for r in resources:z.write(ROOT/r['clipPath'],'audio/'+pathlib.Path(r['clipPath']).name)
print('Catalogues created; zip bytes',zipPath.stat().st_size)
